class Cart:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

class Checkout:
    def __init__(self, cart):
        self.cart = cart

cart = Cart()
cart.add("book")
checkout = Checkout(cart)
print(checkout.cart.items)

from functools import wraps

def announce(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        print("Calling", function.__name__)
        return function(*args, **kwargs)
    return wrapper

@announce
def greet(name):
    return f"Hello, {name}"

print(greet("Ada"))

from contextlib import contextmanager

@contextmanager
def managed_resource():
    print("open")
    try:
        yield "sensor"
    finally:
        print("close")

with managed_resource() as active:
    print(active, "ready")
